sys_script_client.script:
function onSubmit() {
    //MSSCUSTODY-8135
    if (g_scratchpad.isFormValid)
        return true;
    var swiftID = g_form.getValue('tran_reference_for_swift_linking');
    var tradeId = g_form.getDisplayBox('swift_linking_reference').value ? g_form.getDisplayBox('swift_linking_reference').value : g_form.getDisplayBox('swift_linking_reference_id_ref').value;
    var outcome = g_form.getValue('outcome');
    var tasktype = g_form.getValue('trade_task_type');
    var action = g_form.getActionName();
    if (action == 'sysverb_insert_task' && tasktype == 'Maker') {
        if (outcome == 'Rejected SWIFT CANC to Not Be Processed' || outcome == 'Rejected SWIFT CANC to Not Be Processed and Send the SWIFT Copy to Relevant Team'|| outcome =='Manually Update Penalty Details in GHSS'|| outcome =='No Action Required') {
            if (swiftID == '') {
                if (!confirm('Tran Reference for SWIFT Linking not provided. Proceed?')) {
                    return false;
                }
            } else {
                var validateSwiftID = new GlideAjax('HSBCTradeTaskUtils');
                validateSwiftID.addParam('sysparm_name', 'validateSwiftID');
                validateSwiftID.addParam('sysparm_trade_id', tradeId);
                validateSwiftID.getXMLAnswer(swiftValidInfo);
                return false;
            }
        }
    }

    function swiftValidInfo(response) {
        var isTradeID = response;
        if (isTradeID === 'false') {
			//Updated the error message MSSCUSTODY-2472
            if (!confirm('SWIFT Linking Reference ID not found in iQube database. Proceed without Linking?')) {
                return false;
            } else {
                g_form.setValue('tran_reference_for_swift_linking', '');
                g_form.setValue('swift_linking_reference_id', '');
				g_form.setValue('swift_linking_reference', ''); //Added as part of MSSCUSTODY-3122.
            }
        }
        var actionName = g_form.getActionName();
        g_scratchpad.isFormValid = true;
        g_form.submit(actionName);
    }
}
